package com.alsafa.native4;
import android.app.Activity;import android.os.Bundle;import android.view.Gravity;import android.view.ViewGroup;import android.widget.Button;import android.widget.LinearLayout;import android.widget.TextView;import com.alsafa.native4.core.*;import java.util.List;import java.util.Locale;
public final class HandoverActivity extends Activity{private CoreDb db;private Native4Services services;private LinearLayout list;private TextView status;
@Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_handover);db=new CoreDb(this);services=new Native4Services(db,"native4-android-alpha");list=findViewById(R.id.repairList);status=findViewById(R.id.status);findViewById(R.id.pageBack).setOnClickListener(v->finish());findViewById(R.id.refreshRepairs).setOnClickListener(v->refresh());refresh();}
private void refresh(){list.removeAllViews();try{List<RepairWorkflowStore.OpenRepair> rows=services.repairs.openRepairs();if(rows.isEmpty()){status.setText("لا توجد ساعات بانتظار التسليم");return;}status.setText("الساعات الموجودة لدينا: "+rows.size());for(RepairWorkflowStore.OpenRepair r:rows)addRow(r);}catch(Exception e){status.setText("تعذر تحميل الصيانات: "+msg(e));}}
private void addRow(RepairWorkflowStore.OpenRepair r){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(12),dp(10),dp(12),dp(10));box.setBackgroundResource(R.drawable.alsafa_card);TextView t=new TextView(this);t.setGravity(Gravity.END);t.setText((r.invoiceNo==null?"":r.invoiceNo)+" — "+r.customer+"\n"+r.watch+"\nالحالة: "+label(r.status)+" — "+String.format(Locale.US,"%.2f",r.total)+" "+r.currency);box.addView(t);LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);Button ready=new Button(this);ready.setText("جاهز");ready.setEnabled(!"READY".equals(r.status));ready.setOnClickListener(v->set(r,"READY"));Button delivered=new Button(this);delivered.setText("✓ تم التسليم");delivered.setOnClickListener(v->new RepairDeliveryDialog(this,services,status).show(r.repairId));actions.addView(ready,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));actions.addView(delivered,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));box.addView(actions);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.setMargins(0,dp(6),0,dp(6));list.addView(box,lp);}
private void set(RepairWorkflowStore.OpenRepair r,String s){try{services.repairs.setStatus(r.repairId,s);Native4BackgroundSync.request(this);status.setText("✓ "+("READY".equals(s)?"تم تعليم الساعة كجاهزة":"تم تسجيل تسليم الساعة"));refresh();}catch(Exception e){status.setText("تعذر تحديث الصيانة: "+msg(e));}}
private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private static String label(String s){if("READY".equals(s))return "جاهزة";if("IN_PROGRESS".equals(s))return "قيد الصيانة";if("RECEIVED".equals(s))return "مستلمة";return s;}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}}
